@Component("opportunity-handler")
@ProcessingGroup("opportunity-processing-group")
public class OpportunityEventHandler {
	
	// core constructor
	OpportunityEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateOpportunityEvent
     */
    @EventHandler
    public void handle( CreateOpportunityEvent event) {
        entityManager.persist(new Opportunity(event.getOpportunityId(), event.getName(), event.getAmount(), event.getCloseDate(), event.getProbability(), event.getDescription(), event.getOrganization(), event.getAccount(), event.getOwner(), event.getContacts(), event.getLineItems(), event.getStageHistory(), event.getQuotes(), event.getOrders(), event.getCampaigns(), event.getActivities(), event.getTeams(), event.getStage(), event.getType(), event.getForecastCategory()));
    }

    /*
     * @param	event UpdateOpportunityEvent
     */
    @EventHandler
    public Opportunity handle( UpdateOpportunityEvent event) {
    	entityManager.merge(new Opportunity(event.getOpportunityId(), event.getName(), event.getAmount(), event.getCloseDate(), event.getProbability(), event.getDescription(), event.getOrganization(), event.getAccount(), event.getOwner(), event.getContacts(), event.getLineItems(), event.getStageHistory(), event.getQuotes(), event.getOrders(), event.getCampaigns(), event.getActivities(), event.getTeams(), event.getStage(), event.getType(), event.getForecastCategory()));
    }
    
    /*
     * @param	event DeleteOpportunityEvent
     */
    @EventHandler
    public void on( DeleteOpportunityEvent event) {
    	Opportunity entity = new Opportunity();
   
    	// ------------------------------------------
    	// apply the OpportunityId
    	// ------------------------------------------
    	entity.setOpportunityId( event.getOpportunityId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final OpportunityRepository opportunityEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(OpportunityEventHandler.class.getName());

}
